// Workflow 13, Welle 2, AP6: zweistufiger Markt-Screener.
// Stufe A: guenstiges Screening AUSSCHLIESSLICH aus bereits vorhandenen
// DB-Daten (keine neuen FastAPI-Aufrufe fuer diesen Lauf noetig, da das
// aktuelle Datenuniversum == Watchlist ist und taeglich von 01/02/02b
// vollstaendig berechnet wird - siehe docs/MARKTSCANNER.md).
// Stufe B: Auswahl der besten Kandidaten unter konfigurierbaren Obergrenzen
// (Gesamt/Strategie/Sektor/KI-Aufrufe), inkl. Deckungspruefung (Ticker
// ausserhalb der taeglichen 02-Pipeline werden MIT Grund ausgeschlossen,
// nicht mit einem teuren Ad-hoc-Abruf tiefenanalysiert - bewusste
// Vereinfachung fuer Welle 2, siehe docs/MARKTSCANNER.md).

function num(v) { const n = Number(v); return v === null || v === undefined || v === '' || isNaN(n) ? null : n; }
function round(v, d = 3) { if (v === null || v === undefined || isNaN(v)) return null; return parseFloat(Number(v).toFixed(d)); }
function getBusinessDate(date = new Date()) {
  return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Europe/Berlin', year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
}
const heute = getBusinessDate();
const run_id = 'scan-' + heute + '-' + Date.now();

const CFG = {};
for (const r of $('DB: Scanner-Konfiguration laden').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);
const MAX_TOTAL = CFG.SCANNER_MAX_CANDIDATES_TOTAL ?? 15;
const MAX_PER_STRATEGY = CFG.SCANNER_MAX_CANDIDATES_PER_STRATEGY ?? 5;
const MAX_PER_SEKTOR = CFG.SCANNER_MAX_CANDIDATES_PER_SEKTOR ?? 3;
const MAX_AI_CALLS = CFG.SCANNER_MAX_AI_CALLS ?? 15;
const MIN_SCORE_B = CFG.SCANNER_MIN_SCORE_FOR_STAGE_B ?? 0.5;
const MIN_VOLUME_EUR = CFG.SCANNER_MIN_VOLUME_EUR ?? 500000;
const MIN_PRICE = CFG.SCANNER_MIN_PRICE ?? 2.0;

const universum = $('DB: Universum laden').all().map(i => i.json);
const techRows = $('DB: Technische Signale heute laden (Scanner)').all().map(i => i.json);
const strategyRows = $('DB: Strategiesignale heute laden (Scanner)').all().map(i => i.json);
const regimeRows = $('DB: Marktregime laden (Scanner)').all().map(i => i.json);
const priceRows = $('DB: Kursverlauf laden (Scanner)').all().map(i => i.json);
const newsRows = $('DB: News heute laden (Scanner)').all().map(i => i.json);
const fundRows = $('DB: Fundamentaltrend-Basis laden (Scanner)').all().map(i => i.json);

function idx(rows, key) { const m = {}; for (const r of rows) { const k = String(r[key] || '').trim(); if (!k) continue; if (!m[k]) m[k] = []; m[k].push(r); } return m; }
const techByTicker = {}; for (const r of techRows) techByTicker[String(r.ticker || '').trim()] = r;
const stratByTicker = idx(strategyRows, 'ticker');
const priceByTicker = idx(priceRows, 'symbol');
for (const k of Object.keys(priceByTicker)) priceByTicker[k].sort((a, b) => String(a.trading_date).localeCompare(String(b.trading_date)));
const newsByTicker = {};
for (const n of newsRows) {
  const tks = Array.isArray(n.betroffene_ticker_json) ? n.betroffene_ticker_json : [];
  for (const t of tks) { if (!newsByTicker[t]) newsByTicker[t] = []; newsByTicker[t].push(n); }
}
const fundByTicker = idx(fundRows, 'ticker');
const regimeByRegion = {}; for (const r of regimeRows) regimeByRegion[r.region] = r;

function relativeStrength(prices, days) {
  if (!prices || prices.length < days + 1) return null;
  const recent = prices.slice(-(days + 1));
  const closes = recent.map(p => Number(p.close)).filter(v => !isNaN(v));
  if (closes.length < days + 1) return null;
  return round(((closes[closes.length - 1] - closes[0]) / closes[0]) * 100, 2);
}
function volFactorFromPrices(prices) {
  if (!prices || prices.length < 21) return null;
  const vols = prices.slice(-21).map(p => Number(p.volume)).filter(v => !isNaN(v) && v > 0);
  if (vols.length < 10) return null;
  const avg = vols.slice(0, -1).reduce((a, b) => a + b, 0) / (vols.length - 1);
  const last = vols[vols.length - 1];
  return avg > 0 ? round(last / avg, 2) : null;
}

const results = [];
function pushA(ticker, included, reason, score, hint, metrics) {
  results.push({ run_id, business_date: heute, ticker, stage: 'A', included, reason, scan_score: score, strategy_hint: hint, metrics_json: metrics || {} });
}

const survivorsForB = [];
for (const inst of universum) {
  const ticker = inst.ticker;
  const tech = techByTicker[ticker];
  if (!tech) { pushA(ticker, false, 'Keine heutigen technischen Daten vorhanden', null, null, {}); continue; }
  const kurs = num(tech.aktueller_kurs);
  if (kurs === null || kurs <= 0) { pushA(ticker, false, 'Kein gueltiger Kurs', null, null, {}); continue; }
  if (kurs < MIN_PRICE) { pushA(ticker, false, 'Kurs unter Mindestkurs (' + MIN_PRICE + ')', null, null, { kurs }); continue; }
  if (['invalid', 'stale'].includes(tech.data_quality_status)) { pushA(ticker, false, 'Harte Datenqualitaetsstoerung (' + tech.data_quality_status + ')', null, null, {}); continue; }
  if (!inst.exchange) { pushA(ticker, false, 'Boerse unbekannt', null, null, {}); continue; }

  const prices = priceByTicker[ticker] || [];
  if (prices.length < 20) { pushA(ticker, false, 'Zu kurze Kurshistorie fuer Screening (<20 Tage)', null, null, { historyDays: prices.length }); continue; }

  const rs5 = relativeStrength(prices, 5), rs20 = relativeStrength(prices, 20), rs60 = relativeStrength(prices, 60);
  const volFactor = volFactorFromPrices(prices);
  const letzterUmsatz = prices.length ? kurs * Number(prices[prices.length - 1].volume || 0) : null;
  if (letzterUmsatz !== null && letzterUmsatz < MIN_VOLUME_EUR) { pushA(ticker, false, 'Unter Mindest-Tagesumsatz (' + MIN_VOLUME_EUR + ')', null, null, { letzterUmsatz }); continue; }

  const hoch52w = num(tech.hoch_52w), tief52w = num(tech.tief_52w);
  const distHoch = hoch52w ? round((hoch52w - kurs) / hoch52w, 3) : null;
  const distTief = tief52w ? round((kurs - tief52w) / tief52w, 3) : null;

  const fund = fundByTicker[ticker] || [];
  const hatFundamental = fund.length > 0;
  const hatNews = !!(newsByTicker[ticker] && newsByTicker[ticker].length > 0);

  const region = inst.exchange === 'XETRA' ? 'Europa' : (['NASDAQ', 'NYSE'].includes(inst.exchange) ? 'USA' : 'global');
  const regime = regimeByRegion[region] || null;
  const regimeOk = regime && !['stress', 'unknown'].includes(regime.combined_regime);

  let score = 0;
  if (rs20 !== null) score += Math.min(0.25, Math.abs(rs20) / 20 * 0.25);
  if (volFactor !== null && volFactor > 1.2) score += 0.15;
  if (distHoch !== null && distHoch < 0.03) score += 0.15;
  if (distTief !== null && distTief < 0.03) score += 0.15;
  if (regimeOk) score += 0.15;
  if (hatNews) score += 0.15;
  if (hatFundamental) score += 0.10;
  score = round(Math.min(1, score), 3);

  const strat = (stratByTicker[ticker] || []).filter(s => s.direction !== 'neutral').sort((a, b) => Number(b.raw_score || 0) - Number(a.raw_score || 0))[0];
  const metrics = { kurs, rs5, rs20, rs60, volFactor, distHoch, distTief, region, combined_regime: regime ? regime.combined_regime : 'unknown', hatNews, hatFundamental, letzterUmsatz };
  pushA(ticker, true, 'Screening bestanden', score, strat ? strat.strategy : null, metrics);
  if (score >= MIN_SCORE_B) survivorsForB.push({ ticker, score, strategy_hint: strat ? strat.strategy : null, metrics, sektor: inst.sektor });
}

survivorsForB.sort((a, b) => b.score - a.score);
const perStrategyCount = {}; const perSektorCount = {};
let aiCalls = 0;
for (const cand of survivorsForB) {
  const strat = cand.strategy_hint || 'unbekannt';
  if (results.filter(r => r.stage === 'B' && r.included).length >= MAX_TOTAL || aiCalls >= MAX_AI_CALLS) {
    results.push({ run_id, business_date: heute, ticker: cand.ticker, stage: 'B', included: false, reason: 'Obergrenze SCANNER_MAX_CANDIDATES_TOTAL/MAX_AI_CALLS erreicht', scan_score: cand.score, strategy_hint: strat, metrics_json: cand.metrics });
    continue;
  }
  if ((perStrategyCount[strat] || 0) >= MAX_PER_STRATEGY) {
    results.push({ run_id, business_date: heute, ticker: cand.ticker, stage: 'B', included: false, reason: 'Obergrenze SCANNER_MAX_CANDIDATES_PER_STRATEGY (' + strat + ') erreicht', scan_score: cand.score, strategy_hint: strat, metrics_json: cand.metrics });
    continue;
  }
  if (cand.sektor && (perSektorCount[cand.sektor] || 0) >= MAX_PER_SEKTOR) {
    results.push({ run_id, business_date: heute, ticker: cand.ticker, stage: 'B', included: false, reason: 'Obergrenze SCANNER_MAX_CANDIDATES_PER_SEKTOR (' + cand.sektor + ') erreicht', scan_score: cand.score, strategy_hint: strat, metrics_json: cand.metrics });
    continue;
  }
  const hatStrategiesignale = (stratByTicker[cand.ticker] || []).length > 0;
  if (!hatStrategiesignale) {
    results.push({ run_id, business_date: heute, ticker: cand.ticker, stage: 'B', included: false, reason: 'Ticker ausserhalb der taeglichen 02-Pipeline - keine Tiefenanalyse ohne FastAPI-Zusatzabruf (siehe docs/MARKTSCANNER.md)', scan_score: cand.score, strategy_hint: strat, metrics_json: cand.metrics });
    continue;
  }
  perStrategyCount[strat] = (perStrategyCount[strat] || 0) + 1;
  perSektorCount[cand.sektor] = (perSektorCount[cand.sektor] || 0) + 1;
  aiCalls++;
  results.push({ run_id, business_date: heute, ticker: cand.ticker, stage: 'B', included: true, reason: 'Fuer Tiefenanalyse ausgewaehlt', scan_score: cand.score, strategy_hint: strat, metrics_json: cand.metrics });
}

return results.map(r => ({ json: r }));

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgBool(v) { if (v === true) return 'TRUE'; if (v === false) return 'FALSE'; return 'NULL'; }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

const j = $json;
const sql = `INSERT INTO trading.scan_candidates
  (run_id, ticker, stage, included, reason, scan_score, strategy_hint, metrics_json)
  VALUES (${pgStr(j.run_id)}, ${pgStr(j.ticker)}, ${pgStr(j.stage)}, ${pgBool(j.included)}, ${pgStr(j.reason)}, ${pgNum(j.scan_score)}, ${pgStr(j.strategy_hint)}, ${pgJsonb(j.metrics_json)});`;
return { json: { ...j, sql } };

function pgStr(v) { return v === null || v === undefined || v === '' ? 'NULL' : `'` + String(v).replace(/'/g, `''`) + `'`; }
function pgNum(v) { return v === null || v === undefined || v === '' || isNaN(Number(v)) ? 'NULL' : Number(v); }
function pgJsonb(v) { return (v === null || v === undefined) ? "'{}'::jsonb" : `'` + JSON.stringify(v).replace(/'/g, `''`) + `'::jsonb`; }

// Zaehlt aus den bereits berechneten Scan-Kandidaten (nicht erneut aus der DB
// gelesen - Konsistenz mit dem, was tatsaechlich geschrieben wurde).
const alle = $('Stufe A+B: Scan berechnen').all().map(i => i.json);
const universe = $('DB: Universum laden').all().map(i => i.json);
const run_id = alle.length > 0 ? alle[0].run_id : ('scan-' + new Date().toISOString().slice(0, 10) + '-' + Date.now());
const business_date = alle.length > 0 ? alle[0].business_date : new Date().toISOString().slice(0, 10);
const stageASurvivors = alle.filter(r => r.stage === 'A' && r.included).length;
const stageBAnalyzed = alle.filter(r => r.stage === 'B' && r.included).length;
const CFG = {};
for (const r of $('DB: Scanner-Konfiguration laden').all().map(i => i.json)) CFG[r.config_key] = Number(r.value_numeric);

const sql = `INSERT INTO trading.scan_runs
  (run_id, business_date, finished_at, universe_size, stage_a_survivors, stage_b_analyzed, config_snapshot_json, status)
  VALUES (${pgStr(run_id)}, ${pgStr(business_date)}, now(), ${pgNum(universe.length)}, ${pgNum(stageASurvivors)}, ${pgNum(stageBAnalyzed)}, ${pgJsonb(CFG)}, 'success')
  ON CONFLICT (run_id) DO UPDATE SET
    finished_at = EXCLUDED.finished_at, universe_size = EXCLUDED.universe_size,
    stage_a_survivors = EXCLUDED.stage_a_survivors, stage_b_analyzed = EXCLUDED.stage_b_analyzed,
    config_snapshot_json = EXCLUDED.config_snapshot_json, status = EXCLUDED.status;`;
return { json: { run_id, business_date, universeSize: universe.length, stageASurvivors, stageBAnalyzed, sql } };
